function.arguments:
{"command": "cd /workspace/build && cat > compose.py << 'EOF'
"""Original composition: 'Cipher Dawn' - a 150 BPM keygen-style loop in A minor.

Structure (40 bars, 16 rows per bar, speed 6 => 1 bar = 1.6 s):
  intro(4) | A(8) | breakdown B(8) | climax C(8) | A-lift(8) | outro(4)
Order list restarts at the intro, and the outro cadences back onto A minor.
All melodic material below was written for this project.
"""
import sys
sys.path.insert(0, "/workspace/build")
import numpy as np
import synth, xmwrite

ROWS = 16
NCH = 8
# instrument numbers (1-based in XM)
I_KICK, I_SNARE, I_HATC, I_HATO, I_CRASH, I_RISER, I_ARP, I_BASS, I_LEAD, I_HARM, I_PAD = range(1, 12)

# chord tables (MIDI numbers; MIDI 60 = C4 = XM note 49)
ARP = {  # chord tones for the arpeggio (octave 4-5), low -> high
    "Am": [69, 72, 76, 81], "F": [65, 69, 72, 77], "C": [60, 64, 67, 72],
    "G": [67, 71, 74, 79], "E": [64, 68, 71, 76], "Dm": [62, 65, 69, 74],
    "Bb": [58, 62, 65, 70],
}
ROOT = {"Am": 45, "F": 41, "C": 48, "G": 43, "E": 40, "Dm": 38, "Bb": 46}
PCS = {"Am": {9, 0, 4}, "F": {5, 9, 0}, "C": {0, 4, 7}, "G": {7, 11, 2},
       "E": {4, 8, 11}, "Dm": {2, 5, 9}, "Bb": {10, 2, 5}}
PAD = {"Dm": (65, 69), "Am": (72, 76), "Bb": (74, 77), "F": (69, 72),
       "G": (71, 74), "E": (68, 71)}
A_MINOR = {9, 11, 0, 2, 4, 5, 7}


def xn(midi):
    return midi - 11  # MIDI -> XM note number (C-4 = 49)


def volcol(v):
    return 0x10 + max(0, min(64, v))


# ------------------------------------------------------------ melodies
# (midi or None, length in rows); each bar must total 16 rows
MEL_A = [
    [(76, 2), (76, 2), (81, 4), (79, 2), (76, 2), (72, 4)],
    [(77, 2), (81, 2), (84, 4), (81, 2), (77, 2), (72, 4)],
    [(76, 4), (79, 2), (84, 2), (83, 2), (79, 2), (76, 2), (72, 2)],
    [(79, 2), (83, 2), (86, 4), (83, 2), (79, 2), (74, 4)],
    [(84, 2), (81, 2), (79, 2), (76, 2), (81, 4), (79, 2), (76, 2)],
    [(77, 4), (81, 4), (84, 4), (81, 4)],
    [(79, 2), (78, 2), (79, 2), (83, 2), (86, 4), (83, 2), (79, 2)],
    [(80, 4), (83, 2), (76, 2), (71, 4), (68, 4)],
]
MEL_B = [  # breakdown: sparse half-note call
    [(74, 8), (77, 8)], [(76, 8), (72, 8)], [(77, 8), (74, 8)], [(72, 8), (69, 8)],
    [(74, 8), (77, 8)], [(79, 8), (74, 8)], [(81, 8), (76, 8)], [(83, 8), (80, 8)],
]
MEL_C = [  # climax: higher register, 8th/16th-style runs
    [(84, 2), (81, 2), (76, 2), (81, 2), (84, 2), (88, 2), (84, 2), (81, 2)],
    [(89, 2), (84, 2), (81, 2), (77, 2), (84, 4), (81, 2), (77, 2)],
    [(88, 4), (84, 4), (79, 4), (84, 4)],
    [(83, 2), (86, 2), (91, 2), (86, 2), (83, 2), (79, 2), (74, 2), (79, 2)],
    [(88, 2), (84, 2), (81, 4), (84, 2), (88, 2), (91, 2), (88, 2)],
    [(89, 4), (84, 4), (81, 4), (77, 4)],
    [(86, 2), (83, 2), (79, 2), (83, 2), (86, 2), (91, 2), (86, 2), (83, 2)],
    [(92, 4), (88, 4), (83, 4), (80, 4)],
]
# A-lift: first four bars of A raised an octave, last four unchanged
MEL_A2 = [[(m + 12 if m else None, l) for (m, l) in bar] for bar in MEL_A[:4]] + MEL_A[4:]

for mel in (MEL_A, MEL_B, MEL_C, MEL_A2):
    for bar in mel:
        assert sum(l for _, l in bar) == 16 or (sum(l for _, l in bar) == 16), bar


def third_below(m, chord):
    """Harmony line: a third below the lead, preferring chord tones."""
    pcs = PCS[chord]
    for cand in (m - 3, m - 4):
        if cand % 12 in pcs:
            return cand
    for cand in (m - 3, m - 4):
        if cand % 12 in A_MINOR:
            return cand
    return m - 3


# ------------------------------------------------------------ bar builders
def blank():
    return [[(0, 0, 0, 0, 0) for _ in range(NCH)] for _ in range(ROWS)]


def put(p, r, ch, note=None, inst=None, vol=None, eff=None, par=None):
    n, i, v, e, pa = p[r][ch]
    if note is not None: n = note
    if inst is not None: i = inst
    if vol is not None: v = vol
    if eff is not None: e = eff
    if par is not None: pa = par
    p[r][ch] = (n, i, v, e, pa)


def set_arp(p, chord, density, octave_shift=0, seq_kind="updown"):
    notes = ARP[chord]
    if density == 16:
        idx = [0, 1, 2, 3, 2, 1][:]
        seq = [idx[r % 6] for r in range(ROWS)]
        rows = list(range(ROWS))
    else:  # 8ths
        seq = [0, 1, 2, 3, 2, 1, 0, 1]
        rows = list(range(0, ROWS, 2))
    for k, r in enumerate(rows):
        m = notes[seq[k]] + octave_shift
        put(p, r, 2, note=xn(m), inst=I_ARP, vol=volcol(30))


def set_bass(p, chord, mode, fade=0x03):
    root = ROOT[chord]
    if mode == "16":
        for r in range(ROWS):
            m = root if r % 2 == 0 else root + 12
            put(p, r, 3, note=xn(m), inst=I_BASS, eff=0x0A, par=fade)
    elif mode == "8":
        for r in range(0, ROWS, 2):
            put(p, r, 3, note=xn(root), inst=I_BASS, eff=0x0A, par=fade)
    elif mode == "fade":
        put(p, 0, 3, note=xn(root), inst=I_BASS, eff=0x0A, par=0x01)


def set_drums(p, kick_rows, snare_rows, hat_mode, kick_on=True):
    if kick_on:
        for r in kick_rows:
            put(p, r, 4, note=xn(60), inst=I_KICK)
    for r in snare_rows:
        put(p, r, 5, note=xn(60), inst=I_SNARE)
    if hat_mode == "full":
        for r in range(ROWS):
            if r % 4 == 2:
                put(p, r, 6, note=xn(60), inst=I_HATO, vol=volcol(40))
            elif r % 2 == 1:
                put(p, r, 6, note=xn(60), inst=I_HATC, vol=volcol(34))
    elif hat_mode == "offbeat":
        for r in (2, 6, 10, 14):
            put(p, r, 6, note=xn(60), inst=I_HATC, vol=volcol(26))
    elif hat_mode == "open":
        for r in (2, 6, 10, 14):
            put(p, r, 6, note=xn(60), inst=I_HATO, vol=volcol(28))


def set_melody(p, bar, vib=True):
    """Lead on channel 0: notes per token, note-off before rests."""
    r = 0
    prev_on = False
    for (m, L) in bar:
        if m is None:
            if prev_on:
                put(p, r, 0, note=97)
                prev_on = False
        else:
            eff, par = (0, 0)
            if vib and L >= 4:
                eff, par = 0x04, 0x35
            put(p, r, 0, note=xn(m), inst=I_LEAD, vol=volcol(40), eff=eff, par=par)
            prev_on = True
        r += L
    return r


def set_harmony_from_lead(p, bar, chord, octave_shift=0):
    r = 0
    prev_on = False
    for (m, L) in bar:
        if m is None:
            if prev_on:
                put(p, r, 1, note=97)
                prev_on = False
        else:
            h = third_below(m, chord) + octave_shift
            put(p, r, 1, note=xn(h), inst=I_HARM, vol=volcol(26))
            prev_on = True
        r += L


def set_pad(p, chord):
    third, fifth = PAD[chord]
    put(p, 0, 1, note=xn(third), inst=I_PAD, vol=volcol(24))
    put(p, 8, 1, note=xn(fifth), inst=I_PAD, vol=volcol(22))


def make_bar(section, bi, chord, mel_bar):
    p = blank()
    if section == "intro":
        set_arp(p, chord, 8)
        set_drums(p, [0, 4, 8, 12] if bi >= 2 else [], [], "offbeat", kick_on=bi >= 2)
        if bi >= 2:
            set_bass(p, chord, "8", fade=0x02)
    elif section in ("A", "A2"):
        set_arp(p, chord, 16)
        set_bass(p, chord, "16", fade=0x03)
        set_drums(p, [0, 4, 8, 12], [4, 12], "full")
        if mel_bar is not None:
            set_melody(p, mel_bar, vib=True)
            set_harmony_from_lead(p, mel_bar, chord)
    elif section == "B":
        if bi < 4:  # breakdown: no kick, pads and sparse lead
            set_arp(p, chord, 8)
            set_pad(p, chord)
            set_drums(p, [], [], "offbeat", kick_on=False)
        else:       # kick returns, snare roll at the end
            set_arp(p, chord, 8)
            set_bass(p, chord, "8", fade=0x02)
            set_drums(p, [0, 4, 8, 12], [4, 12], "offbeat")
            if bi == 7:
                for r, v in ((8, 20), (10, 26), (12, 30), (13, 34), (14, 40), (15, 48)):
                    put(p, r, 5, note=xn(60), inst=I_SNARE, vol=volcol(v))
        if mel_bar is not None:
            set_melody(p, mel_bar, vib=False)
    elif section == "C":
        set_arp(p, chord, 16, octave_shift=(12 if bi % 2 == 1 else 0))
        set_bass(p, chord, "16", fade=0x03)
        set_drums(p, [0, 4, 8, 12], [4, 10, 12, 14], "full")
        set_melody(p, mel_bar, vib=True)
        set_harmony_from_lead(p, mel_bar, chord)
    elif section == "outro":
        if bi < 3:
            set_arp(p, chord, 8)
            set_bass(p, chord, "8", fade=0x02)
            kr = [0, 8] if bi < 2 else [0, 4, 8]
            set_drums(p, kr, [], "offbeat")
        else:       # final bar: decaying tones and a held Am root, cutting to silence
            put(p, 0, 2, note=xn(69), inst=I_ARP, vol=volcol(30))
            put(p, 4, 2, note=xn(72), inst=I_ARP, vol=volcol(24))
            put(p, 8, 2, note=xn(76), inst=I_ARP, vol=volcol(18))
            set_bass(p, chord, "fade", fade=0x01)
            put(p, 0, 4, note=xn(57), inst=I_KICK) if False else None
            put(p, 0, 4, note=xn(60), inst=I_KICK)
            put(p, 0, 0, note=xn(69), inst=I_LEAD, vol=volcol(28))
            put(p, 12, 0, note=97)
    return p


def build_song():
    # arrangement: (section, chords, melody list or None)
    chords_A = ["Am", "F", "C", "G", "Am", "F", "G", "E"]
    chords_B = ["Dm", "Am", "Bb", "F", "Dm", "G", "Am", "E"]
    plan = []
    for bi, c in enumerate(["Am", "F", "C", "G"]):
        plan.append(("intro", bi, c, None))
    for bi, c in enumerate(chords_A):
        plan.append(("A", bi, c, MEL_A[bi]))
    for bi, c in enumerate(chords_B):
        plan.append(("B", bi, c, MEL_B[bi]))
    for bi, c in enumerate(chords_A):
        plan.append(("C", bi, c, MEL_C[bi]))
    for bi, c in enumerate(chords_A):
        plan.append(("A2", bi, c, MEL_A2[bi]))
    for bi, c in enumerate(["Am", "F", "G", "Am"]):
        plan.append(("outro", bi, c, None))
    return plan


def add_fx(pats_by_bar, plan):
    """Crash on the first row of A, C and A-lift; riser over the last two breakdown bars."""
    idx = {}
    for k, (sec, bi, c, _) in enumerate(plan):
        idx[(sec, bi)] = k
    for (sec, bi) in [("A", 0), ("C", 0), ("A2", 0)]:
