    pans = {0: 0x70, 1: 0x90, 2: 0x50, 3: 0x80, 4: 0x80, 5: 0x7C, 6: 0xB4, 7: 0x80}
    for ch, pv in pans.items():
        put(p, 0, ch, eff=0x08, par=pv)


def main(out_path):
    plan = build_song()
    bar_pats = [make_bar(sec, bi, c, mb) for (sec, bi, c, mb) in plan]
    add_fx(bar_pats, plan)
    set_initial_panning(bar_pats[0])
    # de-duplicate identical patterns
    uniq, order = [], []
    keyof = {}
    for p in bar_pats:
        key = repr(p)
        if key not in keyof:
            keyof[key] = len(uniq)
            uniq.append(p)
        order.append(keyof[key])
    return plan, uniq, order


